static u16 RandomFollowUpMoveExcept(enum RandomTag tag, const u16 *moves, u32 moveCount, u16 excludedMove)
{
    u16 eligibleMoves[moveCount];
    u32 eligibleCount = 0;
    u32 i;

    for (i = 0; i < moveCount; i++)
    {
        if (moves[i] != excludedMove)
            eligibleMoves[eligibleCount++] = moves[i];
    }

    if (eligibleCount == 0)
        return *(const u16 *)RandomElementArray(tag, moves, sizeof(moves[0]), moveCount);

    return *(const u16 *)RandomElementArray(tag, eligibleMoves, sizeof(eligibleMoves[0]), eligibleCount);
}

#define RandomFollowUpMove(tag, moves, battler) \
    RandomFollowUpMoveExcept(tag, moves, ARRAY_COUNT(moves), \
                             gProtectStructs[battler].extraMoveUsed ? MOVE_NONE : gCurrentMove)

static u32 GetMeloettaVerseState(u32 battler)
{
    if (gDisableStructs[battler].uniquePersistentStateActive)
        return UNIQUE_VERSE_OPENING;
    if (gDisableStructs[battler].uniqueOncePerSwitchInUsed)
        return UNIQUE_VERSE_FINAL;
    return UNIQUE_VERSE_NONE;
}

static void SetMeloettaVerseState(u32 battler, u32 state)
{
    gDisableStructs[battler].uniquePersistentStateActive = FALSE;
    gDisableStructs[battler].uniqueOncePerSwitchInUsed = FALSE;

    if (state == UNIQUE_VERSE_OPENING)
        gDisableStructs[battler].uniquePersistentStateActive = TRUE;
    else if (state == UNIQUE_VERSE_FINAL)
        gDisableStructs[battler].uniqueOncePerSwitchInUsed = TRUE;
}

void TryGrantRoyalGimmickEffect(u32 battler)
{
    u32 side = GetBattlerSide(battler);
    u32 partyBit = gBitTable[gBattlerPartyIndexes[battler]];

    if (!IsBattlerAlive(battler)
     || (gBattleStruct->royalGimmickUsed[side] & partyBit))
        return;

    if (HasBattlerAbility(battler, ABILITY_ROYAL_ADVANCE))
        gBattleStruct->switchInTransferFlags[battler] |= SWITCH_IN_TRANSFER_ROYAL_ADVANCE_GIMMICK;
    else if (HasBattlerAbility(battler, ABILITY_ROYAL_GUARD))
        gBattleStruct->switchInTransferFlags[battler] |= SWITCH_IN_TRANSFER_ROYAL_GUARD_GIMMICK;
    else
        return;

    if (!(gBattleStruct->switchInTransferFlags[battler] & (SWITCH_IN_TRANSFER_ROYAL_ADVANCE | SWITCH_IN_TRANSFER_ROYAL_ADVANCE_ACTIVE
                                                        | SWITCH_IN_TRANSFER_ROYAL_GUARD | SWITCH_IN_TRANSFER_ROYAL_GUARD_ACTIVE)))
        gBattleStruct->switchInTransferSourcePartyIdx[battler] = gBattlerPartyIndexes[battler];
    gBattleStruct->royalGimmickUsed[side] |= partyBit;
}

void MarkBattleGimmickUsed(u32 battler)
{
    u32 i;
    u32 gimmickSide = GetBattlerSide(battler);

    gBattleStruct->battleGimmickUsed[gimmickSide] = TRUE;
    for (i = 0; i < gBattlersCount; i++)
    {
        if (GetBattlerSide(i) != gimmickSide)
            TryGrantRoyalGimmickEffect(i);
    }
}

static u16 GetGemItemForType(u32 type)
{
    switch (type)
    {
    case TYPE_NORMAL: return ITEM_NORMAL_GEM;
    case TYPE_FIRE: return ITEM_FIRE_GEM;
    case TYPE_WATER: return ITEM_WATER_GEM;
    case TYPE_ELECTRIC: return ITEM_ELECTRIC_GEM;
    case TYPE_GRASS: return ITEM_GRASS_GEM;
    case TYPE_ICE: return ITEM_ICE_GEM;
    case TYPE_FIGHTING: return ITEM_FIGHTING_GEM;
    case TYPE_POISON: return ITEM_POISON_GEM;
    case TYPE_GROUND: return ITEM_GROUND_GEM;
    case TYPE_FLYING: return ITEM_FLYING_GEM;
    case TYPE_PSYCHIC: return ITEM_PSYCHIC_GEM;
    case TYPE_BUG: return ITEM_BUG_GEM;
    case TYPE_ROCK: return ITEM_ROCK_GEM;
    case TYPE_GHOST: return ITEM_GHOST_GEM;
    case TYPE_DRAGON: return ITEM_DRAGON_GEM;
    case TYPE_DARK: return ITEM_DARK_GEM;
    case TYPE_STEEL: return ITEM_STEEL_GEM;
    case TYPE_FAIRY: return ITEM_FAIRY_GEM;
    default: return ITEM_NONE;
    }
}

static u16 GetRandomGemstashItemForBattler(u32 battler)
{
    u32 i;
    u32 validMoveCount = 0;
    u16 gemItems[MAX_MON_MOVES];
    u8 savedDynamicMoveType = gBattleStruct->dynamicMoveType;
    u8 savedAteBoost = gBattleStruct->ateBoost[battler];
    bool8 savedGemBoost = gSpecialStatuses[battler].gemBoost;

    for (i = 0; i < MAX_MON_MOVES; i++)
    {
        u16 move = gBattleMons[battler].moves[i];
        u32 moveType;
        u16 gemItem;

        if (move == MOVE_NONE || move == MOVE_UNAVAILABLE)
            continue;

        SetTypeBeforeUsingMove(move, battler);
        GET_MOVE_TYPE(move, moveType);
        gemItem = GetGemItemForType(moveType);
        if (gemItem == ITEM_NONE)
            continue;

        gemItems[validMoveCount++] = gemItem;
    }

    gBattleStruct->dynamicMoveType = savedDynamicMoveType;
    gBattleStruct->ateBoost[battler] = savedAteBoost;
    gSpecialStatuses[battler].gemBoost = savedGemBoost;

    if (validMoveCount == 0)
        return ITEM_NONE;

    return gemItems[RandomUniform(RNG_ROGUE_GEMSTASH_TYPE, 0, validMoveCount - 1)];
}

static bool32 IsTrashAlchemyItemRejected(u32 item)
{
    if (Rogue_IsItemRoomReward(item))
        return TRUE;

    switch (ItemId_GetHoldEffect(item))
    {
    case HOLD_EFFECT_NONE:
    case HOLD_EFFECT_EXP_SHARE:
    case HOLD_EFFECT_PLATE:
    case HOLD_EFFECT_DRIVE:
    case HOLD_EFFECT_MEGA_STONE:
    case HOLD_EFFECT_MEMORY:
    case HOLD_EFFECT_Z_CRYSTAL:
    case HOLD_EFFECT_MASK:
    case HOLD_EFFECT_PRIMAL_ORB:
    case HOLD_EFFECT_SOUL_DEW:
    case HOLD_EFFECT_ADAMANT_ORB:
    case HOLD_EFFECT_LUSTROUS_ORB:
    case HOLD_EFFECT_GRISEOUS_ORB:
    case HOLD_EFFECT_BERSERK_GENE:
        return TRUE;
    default:
        return FALSE;
    }
}

static u16 GetRandomTrashAlchemyItem(void)
{
    return RandomUniformExcept(RNG_ROGUE_TRASH_ALCHEMY_ITEM, ITEM_NONE + 1, ITEMS_COUNT - 1, IsTrashAlchemyItemRejected);
}

