static bool32 TryUseParadoxSignatureCalledMove(u32 battler, u32 target, u32 ability, u32 calledMove)
{
    if (calledMove == MOVE_BURNING_BULWARK)
    {
        if (!CanUseSelfExtraMove(battler))
            return FALSE;
        target = battler;
    }
    else if (target >= gBattlersCount
          || !IsBattlerAlive(target)
          || GetBattlerSide(target) == GetBattlerSide(battler)
          || !CanUseExtraMove(battler, target))
    {
        return FALSE;
    }

    SetBattlerTriggeredAbility(battler, ability);
    SetAtkCancellerForCalledMove();
    gBattlerAttacker = gBattlerAbility = battler;
    gBattlerTarget = target;
    gCalledMove = calledMove;
    gHitMarker &= ~HITMARKER_ATTACKSTRING_PRINTED;
    gProtectStructs[battler].extraMoveUsed = TRUE;
    gDisableStructs[battler].uniqueOncePerSwitchInUsed = TRUE;
    StartAbilityCalledMoveScript();
    return TRUE;
}

static bool32 TryUseSurgeProtocolCalledMove(u32 battler, u32 move)
{
    u32 target;

    if (move == MOVE_CHARGE)
    {
        if (!CanUseSelfExtraMove(battler))
            return FALSE;

        target = battler;
        gDisableStructs[battler].uniqueOncePerSwitchInUsed = TRUE;
    }
    else
    {
        if (gSideStatuses[GetBattlerSide(BATTLE_OPPOSITE(battler))] & SIDE_STATUS_STEALTH_ROCK)
            return FALSE;
        if (!TryGetOpposingExtraMoveTarget(battler, &target))
            return FALSE;

        gDisableStructs[battler].uniquePersistentStateActive = TRUE;
    }

    SetBattlerTriggeredAbility(battler, ABILITY_SURGE_PROTOCOL);
    SetAtkCancellerForCalledMove();
    gBattlerAttacker = gBattlerAbility = battler;
    gBattlerTarget = target;
    gCalledMove = move;
    gHitMarker &= ~HITMARKER_ATTACKSTRING_PRINTED;
    gProtectStructs[battler].extraMoveUsed = TRUE;
    StartAbilityCalledMoveScript();
    return TRUE;
}

static bool32 ShouldDualitySwapOffensiveStats(u32 battlerAtk, u32 move, u32 moveType)
{
    return HasBattlerAbility(battlerAtk, ABILITY_DUALITY)
        && gDisableStructs[battlerAtk].uniquePersistentStateActive
        && gBattleMoves[move].effect != EFFECT_FOUL_PLAY
        && gBattleMoves[move].effect != EFFECT_BODY_PRESS
        && !HasBattlerAbility(battlerAtk, ABILITY_ANCIENT_IDOL)
        && !(HasBattlerAbility(battlerAtk, ABILITY_UPROOT)
          && (gStatuses3[battlerAtk] & STATUS3_ROOTED)
          && moveType == TYPE_GRASS);
}

static u32 GetStagedOffensiveStat(u32 battler, u32 statId)
{
    u32 stat = (statId == STAT_ATK) ? gBattleMons[battler].attack : gBattleMons[battler].spAttack;
    u32 stage = gBattleMons[battler].statStages[statId];

    return stat * gStatStageRatios[stage][0] / gStatStageRatios[stage][1];
}

static u32 GetDualityModeMessage(u32 battler)
{
    u32 attackStatId = gDisableStructs[battler].uniquePersistentStateActive ? STAT_SPATK : STAT_ATK;
    u32 spAttackStatId = gDisableStructs[battler].uniquePersistentStateActive ? STAT_ATK : STAT_SPATK;
    u32 effectiveAttack = GetStagedOffensiveStat(battler, attackStatId);
    u32 effectiveSpAttack = GetStagedOffensiveStat(battler, spAttackStatId);

    if (effectiveAttack > effectiveSpAttack)
        return B_MSG_DUALITY_BODY;
    if (effectiveSpAttack > effectiveAttack)
        return B_MSG_DUALITY_MIND;
    return B_MSG_DUALITY_BALANCED;
}

static bool32 ShouldTallTaleUseSpAttackForDragonHammer(u32 battlerAtk, u32 move)
{
    return move == MOVE_DRAGON_HAMMER
        && HasBattlerAbility(battlerAtk, ABILITY_TALL_TALE)
        && GetStagedOffensiveStat(battlerAtk, STAT_SPATK) > GetStagedOffensiveStat(battlerAtk, STAT_ATK);
}

static bool32 CanUseSelfExtraMoveAfterMoveEndDamage(u32 battlerAttacker, u32 move)
{
    u32 pendingDamage = 0;

    if (CanUseSelfExtraMove(battlerAttacker))
    {
        if (!IsBattlerProtectedByRecoilCharm(battlerAttacker)
         && (move == MOVE_STRUGGLE || !HasBattlerAbility(battlerAttacker, ABILITY_ROCK_HEAD)))
        {
            switch (gBattleMoves[move].effect)
            {
            case EFFECT_RECOIL_25:
                pendingDamage += max(1, gBattleScripting.savedDmg / 4);
                break;
            case EFFECT_RECOIL_33:
            case EFFECT_RECOIL_33_STATUS:
                pendingDamage += max(1, gBattleScripting.savedDmg / 3);
                break;
            case EFFECT_RECOIL_50:
                pendingDamage += max(1, gBattleScripting.savedDmg / 2);
                break;
            case EFFECT_RECOIL_HP_25:
                pendingDamage += max(1, GetNonDynamaxMaxHP(battlerAttacker) / 4);
                break;
            }
        }

        if (!(gMoveResultFlags & MOVE_RESULT_NO_EFFECT)
         && TARGET_TURN_DAMAGED
         && IsMoveMakingContact(move, battlerAttacker)
         && IsBattlerAlive(gBattlerTarget)
         && GetBattlerHoldEffect(gBattlerTarget, TRUE) == HOLD_EFFECT_ROCKY_HELMET
         && !HasBattlerAbility(battlerAttacker, ABILITY_MAGIC_GUARD))
        {
            pendingDamage += max(1, GetNonDynamaxMaxHP(battlerAttacker) / 6);
        }

        if (GetBattlerHoldEffect(battlerAttacker, TRUE) == HOLD_EFFECT_LIFE_ORB
         && !TestSheerForceFlag(battlerAttacker, move)
         && !HasBattlerAbility(battlerAttacker, ABILITY_MAGIC_GUARD)
         && !gSpecialStatuses[battlerAttacker].preventLifeOrbDamage
         && gSpecialStatuses[battlerAttacker].damagedMons)
        {
            pendingDamage += max(1, GetNonDynamaxMaxHP(battlerAttacker) / 10);
        }

        return gBattleMons[battlerAttacker].hp > pendingDamage;
    }

    return FALSE;
}

