void QueueMoonlightForHeal(u32 healedBattler, u32 healAmount)
{
    u32 i;
    u8 battlers[MAX_BATTLERS_COUNT] = {0, 1, 2, 3};

    if (healedBattler >= gBattlersCount
     || healAmount == 0
     || gBattleStruct->suppressMoonlightHealQueue)
        return;

    SortBattlersBySpeed(battlers, FALSE);
    for (i = 0; i < gBattlersCount; i++)
    {
        u32 battler = battlers[i];

        if (!IsBattlerAlive(battler)
         || !HasBattlerAbility(battler, ABILITY_MOONLIGHT)
         || IsBattlerHealBlocked(battler))
            continue;

        if (battler == healedBattler)
        {
            u32 healedHp = min(gBattleMons[battler].maxHP, gBattleMons[battler].hp + healAmount);
            if (healedHp >= gBattleMons[battler].maxHP)
                continue;
        }
        else if (BATTLER_MAX_HP(battler))
        {
            continue;
        }

        QueuePendingUniqueAbilityEffect(PENDING_UNIQUE_EFFECT_MOONLIGHT, battler, healedBattler, healedBattler);
    }
}

void QueueLastPourForHeal(u32 battler)
{
    u32 side;
    u32 partyBit;

    if (battler >= gBattlersCount
     || !IsBattlerAlive(battler)
     || !HasBattlerAbility(battler, ABILITY_LAST_POUR)
     || !CanUseSelfExtraMove(battler))
        return;

    side = GetBattlerSide(battler);
    partyBit = gBitTable[gBattlerPartyIndexes[battler]];
    if (gBattleStruct->uniqueAbilityUsed[side] & partyBit)
        return;

    if (QueuePendingUniqueAbilityEffect(PENDING_UNIQUE_EFFECT_LAST_POUR, battler, battler, battler))
        gBattleStruct->uniqueAbilityUsed[side] |= partyBit;
}

void QueueCounterstepForSpeedRise(u32 battler)
{
    u32 i;
    u8 battlers[MAX_BATTLERS_COUNT] = {0, 1, 2, 3};

    if (battler >= gBattlersCount
     || !IsBattlerAlive(battler)
     || gBattleStruct->isAtkCancelerForCalledMove)
        return;

    SortBattlersBySpeed(battlers, FALSE);
    for (i = 0; i < gBattlersCount; i++)
    {
        u32 counterstepBattler = battlers[i];

        if (IsBattlerAlive(counterstepBattler)
         && GetBattlerSide(counterstepBattler) != GetBattlerSide(battler)
         && HasBattlerAbility(counterstepBattler, ABILITY_COUNTERSTEP)
         && CanUseExtraMove(counterstepBattler, battler))
        {
            QueuePendingUniqueAbilityEffect(
                PENDING_UNIQUE_EFFECT_COUNTERSTEP,
                counterstepBattler,
                battler,
                battler);
        }
    }
}

void QueueBitterRuseForTypeImmunity(void)
{
    u32 moveUser = gBattlerAttacker;
    u32 disguisedBattler = gBattlerTarget;
    u32 moveType;

    if (moveUser >= gBattlersCount
     || disguisedBattler >= gBattlersCount
     || GetBattlerSide(moveUser) == GetBattlerSide(disguisedBattler)
     || !HasBattlerAbility(disguisedBattler, ABILITY_BITTER_RUSE)
     || GetIllusionMonPtr(disguisedBattler) == NULL
     || !(gMoveResultFlags & MOVE_RESULT_DOESNT_AFFECT_FOE)
     || (gMoveResultFlags & (MOVE_RESULT_MISSED | MOVE_RESULT_FAILED))
     || (gHitMarker & HITMARKER_UNABLE_TO_USE_MOVE)
     || gProtectStructs[moveUser].confusionSelfDmg)
        return;

    GET_MOVE_TYPE(gCurrentMove, moveType);
    if (CalcTypeEffectivenessMultiplier(
            gCurrentMove,
            moveType,
            moveUser,
            disguisedBattler,
            ABILITY_NONE,
            FALSE) != UQ_4_12(0.0))
        return;

    QueuePendingUniqueAbilityEffect(
        PENDING_UNIQUE_EFFECT_BITTER_RUSE,
        disguisedBattler,
        moveUser,
        moveUser);
}

static bool32 TryActivateAromaTrail(u32 battler, u32 source, u32 target)
{
    if (!IsBattlerAlive(battler)
     || !IsBattlerAlive(source)
     || !IsBattlerAlive(target)
     || !HasBattlerAbility(battler, ABILITY_AROMA_TRAIL)
     || GetBattlerSide(battler) == GetBattlerSide(source)
     || (gBattleMons[target].statStages[STAT_ACC] == MIN_STAT_STAGE
      && GetBattlerAbility(target) != ABILITY_MIRROR_ARMOR))
        return FALSE;

    SET_STATCHANGER(STAT_ACC, 1, TRUE);
    SetBattlerTriggeredAbility(battler, ABILITY_AROMA_TRAIL);
    gBattlerAttacker = gBattlerAbility = battler;
    gBattlerTarget = target;
    BattleScriptPushCursor();
    gBattlescriptCurrInstr = BattleScript_AromaTrailActivates;
    return TRUE;
}

static bool32 TryActivateMoonlight(u32 battler, u32 source, u32 target)
{
    if (!IsBattlerAlive(battler)
     || source >= gBattlersCount
     || target >= gBattlersCount
     || !HasBattlerAbility(battler, ABILITY_MOONLIGHT)
     || BATTLER_MAX_HP(battler)
     || IsBattlerHealBlocked(battler))
        return FALSE;

    SetBattlerTriggeredAbility(battler, ABILITY_MOONLIGHT);
    gBattlerAttacker = gBattlerAbility = battler;
    gBattleMoveDamage = GetNonDynamaxMaxHP(battler) / 8;
    if (gBattleMoveDamage == 0)
        gBattleMoveDamage = 1;
    gBattleMoveDamage *= -1;
    gBattleStruct->suppressMoonlightHealQueue = TRUE;
    BattleScriptPushCursor();
    gBattlescriptCurrInstr = BattleScript_MoonlightActivates;
    return TRUE;
}

static bool32 TryActivateStaticStash(u32 battler)
{
    if (!IsBattlerAlive(battler)
     || !HasBattlerAbility(battler, ABILITY_STATIC_STASH)
     || !CanUseSelfExtraMove(battler))
        return FALSE;

    SetBattlerTriggeredAbility(battler, ABILITY_STATIC_STASH);
    SetAtkCancellerForCalledMove();
    gBattlerAttacker = gBattlerAbility = gBattlerTarget = battler;
    gCalledMove = MOVE_CHARGE;
    gHitMarker &= ~HITMARKER_ATTACKSTRING_PRINTED;
    gProtectStructs[battler].extraMoveUsed = TRUE;
    StartAbilityCalledMoveScript();
    return TRUE;
}

