u32 GetBattlerHoldEffect(u32 battler, bool32 checkNegating)
{
    if (checkNegating)
    {
        if (gStatuses3[battler] & STATUS3_EMBARGO)
            return HOLD_EFFECT_NONE;
        if (gFieldStatuses & STATUS_FIELD_MAGIC_ROOM)
            return HOLD_EFFECT_NONE;
        if (HasBattlerAbility(battler, ABILITY_KLUTZ))
            return HOLD_EFFECT_NONE;
    }

    gPotentialItemEffectBattler = battler;

    if (gBattleMons[battler].item == ITEM_ENIGMA_BERRY_E_READER)
        return gEnigmaBerries[battler].holdEffect;
    else
        return ItemId_GetHoldEffect(gBattleMons[battler].item);
}

static u32 GetBattlerItemHoldEffectParam(u32 battler, u32 item)
{
    if (item == ITEM_ENIGMA_BERRY_E_READER)
        return gEnigmaBerries[battler].holdEffectParam;
    else
        return ItemId_GetHoldEffectParam(item);
}

u32 GetBattlerHoldEffectParam(u32 battler)
{
    if (gBattleMons[battler].item == ITEM_ENIGMA_BERRY_E_READER)
        return gEnigmaBerries[battler].holdEffectParam;
    else
        return ItemId_GetHoldEffectParam(gBattleMons[battler].item);
}

bool32 IsMoveInherentlyMakingContact(u32 move)
{
    return gBattleMoves[move].makesContact
        || (gBattleMoves[move].effect == EFFECT_SHELL_SIDE_ARM && gBattleStruct->swapDamageCategory);
}

bool32 IsMoveMakingContact(u32 move, u32 battlerAtk)
{
    u32 atkHoldEffect = GetBattlerHoldEffect(battlerAtk, TRUE);

    if (!IsMoveInherentlyMakingContact(move))
        return FALSE;
    else if ((atkHoldEffect == HOLD_EFFECT_PUNCHING_GLOVE && gBattleMoves[move].punchingMove)
           || atkHoldEffect == HOLD_EFFECT_PROTECTIVE_PADS
           || HasBattlerAbility(battlerAtk, ABILITY_LONG_REACH)
           || (GetBattlerSide(battlerAtk) == B_SIDE_PLAYER && IsCharmActive(EFFECT_REACH_DAMAGE))
           || (GetBattlerSide(battlerAtk) == B_SIDE_OPPONENT && IsCurseActive(EFFECT_REACH_DAMAGE))
           || (HasBattlerAbility(battlerAtk, ABILITY_AFTERIMAGE)
            && gBattlerAttacker == battlerAtk
            && gBattlerTarget < gBattlersCount
            && GetBattlerTurnOrderNum(battlerAtk) < GetBattlerTurnOrderNum(gBattlerTarget))
           || (HasBattlerAbility(battlerAtk, ABILITY_CRACKLING_SHRINE)
            && IsBattlerTerrainAffected(battlerAtk, STATUS_FIELD_ELECTRIC_TERRAIN)))
    {
        return FALSE;
    }
    else
    {
        return TRUE;
    }
}

s32 ApplyRecoveryCharmHealing(u32 battler, s32 healing)
{
    if (GetBattlerSide(battler) == B_SIDE_PLAYER && IsCharmActive(EFFECT_RECOVERY))
        healing = healing * 3 / 2;

    return healing;
}

bool32 IsBattlerProtectedByRecoilCharm(u32 battler)
{
    return battler < gBattlersCount
        && GetBattlerSide(battler) == B_SIDE_PLAYER
        && IsCharmActive(EFFECT_RECOIL_PROTECTION);
}

static bool32 IsMoveBlockedByProtectLike(u32 battler, u32 move)
{
    if (gBattleMoves[move].ignoresProtect)
        return FALSE;
    else if (gProtectStructs[battler].protected)
        return TRUE;
    else if (gSideStatuses[GetBattlerSide(battler)] & SIDE_STATUS_WIDE_GUARD
             && GetBattlerMoveTargetType(gBattlerAttacker, move) & (MOVE_TARGET_BOTH | MOVE_TARGET_FOES_AND_ALLY))
        return TRUE;
    else if (gProtectStructs[battler].banefulBunkered)
        return TRUE;
    else if (gProtectStructs[battler].burningBulwarked)
        return TRUE;
    else if ((gProtectStructs[battler].obstructed || gProtectStructs[battler].silkTrapped) && !IS_MOVE_STATUS(move))
        return TRUE;
    else if (gProtectStructs[battler].spikyShielded)
        return TRUE;
    else if (gProtectStructs[battler].kingsShielded && gBattleMoves[move].power != 0)
        return TRUE;
    else if (gProtectStructs[battler].maxGuarded)
        return TRUE;
    else if (gSideStatuses[GetBattlerSide(battler)] & SIDE_STATUS_QUICK_GUARD
             && GetExecutingMovePriority(gBattlerAttacker) > 0)
        return TRUE;
    else if (gSideStatuses[GetBattlerSide(battler)] & SIDE_STATUS_CRAFTY_SHIELD
      && IS_MOVE_STATUS(move))
        return TRUE;
    else if (gSideStatuses[GetBattlerSide(battler)] & SIDE_STATUS_MAT_BLOCK
      && !IS_MOVE_STATUS(move))
        return TRUE;
    else
        return FALSE;
}

bool32 IsBattlerProtected(u32 battler, u32 move)
{
    // Decorate bypasses protect and detect, but not crafty shield
    if (move == MOVE_DECORATE)
    {
        if (gSideStatuses[GetBattlerSide(battler)] & SIDE_STATUS_CRAFTY_SHIELD)
            return TRUE;
        else if (gProtectStructs[battler].protected)
            return FALSE;
    }

    // Z-Moves and Max Moves bypass protection (except Max Guard).
    if ((IsMaxMove(move) || gBattleStruct->zmove.active)
         && (!gProtectStructs[battler].maxGuarded
             || gBattleMoves[move].argument == MAX_EFFECT_BYPASS_PROTECT))
        return FALSE;

    // Max Guard is silly about the moves it blocks, including Teatime.
    if (gProtectStructs[battler].maxGuarded && IsMoveBlockedByMaxGuard(move))
        return TRUE;

    // Protective Pads doesn't stop Unseen Fist from bypassing Protect effects, so IsMoveMakingContact() isn't used here.
    // This means extra logic is needed to handle Shell Side Arm.
    if (IsMoveMakingContact(move, gBattlerAttacker)
        && IsMoveBlockedByProtectLike(battler, move)
        && !gProtectStructs[battler].maxGuarded
        && (HasBattlerAbility(gBattlerAttacker, ABILITY_PIERCING_DRILL)
         || (HasBattlerAbility(gBattlerAttacker, ABILITY_SIEGE_INSTINCT)
          && IsOnlyParadoxInParty(gBattlerAttacker))))
    {
        gProtectStructs[gBattlerAttacker].touchedProtectLike = TRUE;
        return FALSE;
    }
    else if (HasBattlerAbility(gBattlerAttacker, ABILITY_UNSEEN_FIST)
        && (gBattleMoves[move].makesContact || (gBattleMoves[move].effect == EFFECT_SHELL_SIDE_ARM && gBattleStruct->swapDamageCategory))
        && !gProtectStructs[battler].maxGuarded) // Max Guard cannot be bypassed by Unseen Fist
        return FALSE;
    else if (HasBattlerAbility(gBattlerAttacker, ABILITY_X_RAY_JAWS)
        && gBattleMoves[move].bitingMove
        && !gProtectStructs[battler].maxGuarded)
        return FALSE;
    else if (HasBattlerAbility(gBattlerAttacker, ABILITY_RIFT)
        && gDisableStructs[gBattlerAttacker].uniquePersistentStateActive
        && !IS_MOVE_STATUS(move)
        && !gProtectStructs[battler].maxGuarded)
        return FALSE;

    return IsMoveBlockedByProtectLike(battler, move);
}

bool32 IsInverseBattleActive(void)
{
    u32 battler;

    if (B_FLAG_INVERSE_BATTLE != 0 && FlagGet(B_FLAG_INVERSE_BATTLE))
        return TRUE;

    if (!gMain.inBattle)
        return FALSE;

    for (battler = 0; battler < gBattlersCount; battler++)
    {
        if (IsBattlerAlive(battler)
         && HasBattlerAbilityIgnoreMoldBreaker(battler, ABILITY_MIRROR_WORLD))
            return TRUE;
    }

    return FALSE;
}

// Only called directly when calculating damage type effectiveness
static bool32 IsBattlerGrounded2(u32 battler, bool32 considerInverse)
{
    u32 holdEffect = GetBattlerHoldEffect(battler, TRUE);

    if (holdEffect == HOLD_EFFECT_IRON_BALL)
        return TRUE;
    if (gFieldStatuses & STATUS_FIELD_GRAVITY)
        return TRUE;
    if (B_ROOTED_GROUNDING >= GEN_4 && gStatuses3[battler] & STATUS3_ROOTED)
        return TRUE;
    if (gStatuses3[battler] & STATUS3_SMACKED_DOWN)
        return TRUE;
    if (gStatuses3[battler] & STATUS3_TELEKINESIS)
        return FALSE;
    if (gStatuses3[battler] & STATUS3_MAGNET_RISE)
        return FALSE;
    if (holdEffect == HOLD_EFFECT_AIR_BALLOON)
        return FALSE;
    if (HasBattlerAbility(battler, ABILITY_LEVITATE)
     || HasBattlerAbility(battler, ABILITY_EELEVATE)
     || HasBattlerAbility(battler, ABILITY_SHORT_CIRCUIT))
        return FALSE;
    if (HasBattlerAbility(battler, ABILITY_BRANCH_SWING)
     && (gFieldStatuses & STATUS_FIELD_GRASSY_TERRAIN))
        return FALSE;
    if (IS_BATTLER_OF_TYPE(battler, TYPE_FLYING) && (!considerInverse || !IsInverseBattleActive()))
        return FALSE;
    return TRUE;
}

bool32 IsBattlerGrounded(u32 battler)
{
    return IsBattlerGrounded2(battler, FALSE);
}

bool32 IsBattlerAlive(u32 battler)
{
    if (battler >= gBattlersCount)
        return FALSE;
    else if (gBattleMons[battler].hp == 0)
        return FALSE;
    else if (gAbsentBattlerFlags & gBitTable[battler])
        return FALSE;
    else
        return TRUE;
}

u32 GetMoveSlot(u16 *moves, u32 move)
{
    u32 i;

    for (i = 0; i < MAX_MON_MOVES; i++)
    {
        if (moves[i] == move)
            break;
    }
    return i;
}

u32 GetBattlerWeight(u32 battler)
{
    u32 i;
    u32 weight = GetSpeciesWeight(gBattleMons[battler].species);
    u32 ability = GetBattlerAbility(battler);
    u32 holdEffect = GetBattlerHoldEffect(battler, TRUE);

    if (ability == ABILITY_HEAVY_METAL)
        weight *= 2;
    else if (ability == ABILITY_LIGHT_METAL)
        weight /= 2;

    if (holdEffect == HOLD_EFFECT_FLOAT_STONE)
        weight /= 2;

    for (i = 0; i < gDisableStructs[battler].autotomizeCount; i++)
    {
        if (weight > 1000)
        {
            weight -= 1000;
        }
        else if (weight <= 1000)
        {
            weight = 1;
            break;
        }
    }

    if (weight == 0)
        weight = 1;

    return weight;
}

u32 CountBattlerStatIncreases(u32 battler, bool32 countEvasionAcc)
{
    u32 i;
    u32 count = 0;

    for (i = 0; i < NUM_BATTLE_STATS; i++)
    {
        if ((i == STAT_ACC || i == STAT_EVASION) && !countEvasionAcc)
            continue;
        if (gBattleMons[battler].statStages[i] > DEFAULT_STAT_STAGE) // Stat is increased.
            count += gBattleMons[battler].statStages[i] - DEFAULT_STAT_STAGE;
    }

    return count;
}

u32 GetMoveTargetCount(u32 move, u32 battlerAtk, u32 battlerDef)
{
    switch (GetBattlerMoveTargetType(gBattlerAttacker, move))
    {
    case MOVE_TARGET_BOTH:
        return IsBattlerAlive(battlerDef)
             + IsBattlerAlive(BATTLE_PARTNER(battlerDef));
    case MOVE_TARGET_FOES_AND_ALLY:
        return IsBattlerAlive(battlerDef)
             + IsBattlerAlive(BATTLE_PARTNER(battlerDef))
             + IsBattlerAlive(BATTLE_PARTNER(battlerAtk));
    case MOVE_TARGET_OPPONENTS_FIELD:
        return 1;
    case MOVE_TARGET_DEPENDS:
    case MOVE_TARGET_SELECTED:
    case MOVE_TARGET_RANDOM:
    case MOVE_TARGET_USER_OR_SELECTED:
        return IsBattlerAlive(battlerDef);
    case MOVE_TARGET_USER:
        return IsBattlerAlive(battlerAtk);
    default:
        return 0;
    }
}

