bool8 CanMonParticipateInSkyBattle(struct Pokemon *mon)
{
    u16 species = GetMonData(mon, MON_DATA_SPECIES);
    u16 monAbilityNum = GetMonData(mon, MON_DATA_ABILITY_NUM, NULL);

    bool8 hasLevitateAbility = gSpeciesInfo[species].abilities[monAbilityNum] == ABILITY_LEVITATE
                             || gSpeciesInfo[species].abilities[monAbilityNum] == ABILITY_EELEVATE;
    u32 otId = GetMonData(mon, MON_DATA_OT_ID);
    bool8 isFlyingType = GetTypeBySpecies(species, 0, otId) == TYPE_FLYING || GetTypeBySpecies(species, 1, otId) == TYPE_FLYING;
    bool8 monIsValidAndNotEgg = GetMonData(mon, MON_DATA_SANITY_HAS_SPECIES) && !GetMonData(mon, MON_DATA_IS_EGG);

    if (monIsValidAndNotEgg)
    {
        if ((hasLevitateAbility || isFlyingType) && !IsMonBannedFromSkyBattles(species))
            return TRUE;
    }
    return FALSE;
}

bool8 IsMonBannedFromSkyBattles(u16 species)
{
    switch (species)
    {
#if B_SKY_BATTLE_STRICT_ELIGIBILITY == TRUE
        case SPECIES_SPEAROW:
        case SPECIES_FARFETCHD:
        case SPECIES_DODUO:
        case SPECIES_DODRIO:
        case SPECIES_HOOTHOOT:
        case SPECIES_NATU:
        case SPECIES_MURKROW:
        case SPECIES_DELIBIRD:
        case SPECIES_TAILLOW:
        case SPECIES_STARLY:
        case SPECIES_CHATOT:
        case SPECIES_SHAYMIN:
        case SPECIES_PIDOVE:
        case SPECIES_ARCHEN:
        case SPECIES_DUCKLETT:
        case SPECIES_RUFFLET:
        case SPECIES_VULLABY:
        case SPECIES_FLETCHLING:
        case SPECIES_HAWLUCHA:
        case SPECIES_ROWLET:
        case SPECIES_PIKIPEK:
#endif
        case SPECIES_EGG:
            return TRUE;
        default:
            return FALSE;
    }
}

static bool32 IsGraveglassActive(u32 battler)
{
    return gBattleMons[battler].item == ITEM_GRAVEGLASS
        && GetBattlerHoldEffect(battler, TRUE) == HOLD_EFFECT_GRAVEGLASS;
}

u8 GetBattlerType(u32 battler, u8 typeIndex, bool32 ignoreTera)
{
    u32 chromaticType = GetBattlerChromaticFluxType(battler);
    u32 teraType = GetBattlerTeraType(battler);
    u16 types[3] = {0};
    types[0] = gBattleMons[battler].type1;
    types[1] = gBattleMons[battler].type2;
    types[2] = gBattleMons[battler].type3;

    if (IS_STANDARD_TYPE(chromaticType)
     && HasBattlerAbilityIgnoreMoldBreaker(battler, ABILITY_CHROMATIC_FLUX))
        return typeIndex == 2 ? TYPE_MYSTERY : chromaticType;

    // Handle Terastallization
    if (IsTerastallized(battler) && teraType != TYPE_STELLAR && !ignoreTera)
        return GetBattlerTeraType(battler);

    // Phantom Stone fills the unused second slot for a monotype and the dynamic
    // third slot for a dual-type. Keep this derived so item suppression,
    // removal, form changes, and other runtime type changes are respected.
    if (IsGraveglassActive(battler)
     && types[0] != TYPE_GHOST
     && types[1] != TYPE_GHOST
     && types[2] != TYPE_GHOST)
    {
        if (types[1] == types[0] || !IS_STANDARD_TYPE(types[1]))
            types[1] = TYPE_GHOST;
        else if (types[2] == TYPE_MYSTERY)
            types[2] = TYPE_GHOST;
    }

    // Handle Roost's Flying-type suppression
    if (typeIndex == 0 || typeIndex == 1)
    {
        if (gBattleResources->flags->flags[battler] & RESOURCE_FLAG_ROOST
            && !IsTerastallized(battler))
        {
            if (types[0] == TYPE_FLYING && types[1] == TYPE_FLYING)
                return B_ROOST_PURE_FLYING >= GEN_5 ? TYPE_NORMAL : TYPE_MYSTERY;
            else
                return types[typeIndex] == TYPE_FLYING ? TYPE_MYSTERY : types[typeIndex];
        }
    }

    return types[typeIndex];
}

void RemoveBattlerType(u32 battler, u8 type)
{
    u32 i;
    if (IsTerastallized(battler)) // don't remove type if Terastallized
        return;
    for (i = 0; i < 3; i++)
    {
        if (*(u8 *)(&gBattleMons[battler].type1 + i) == type)
            *(u8 *)(&gBattleMons[battler].type1 + i) = TYPE_MYSTERY;
    }
}
